#include <iostream>
using namespace std;

class Cat {
public:
    const int fish;

    Cat(int f) : fish(f) {}

    void show() const {
        cout << "本喵有 " << fish << " 条小鱼干" << endl;
    }
};

int main() {
    Cat c1({fish});
    c1.show();
    return 0;
}
